## C++ benchmark (`tests/core/variant/test_bench_container_validate.cpp`)

```cpp
#include "tests/test_macros.h"

TEST_FORCE_LINK(test_bench_container_validate)

#include "core/variant/array.h"
#include "core/variant/dictionary.h"

#include <algorithm>
#include <chrono>
#include <cstdio>

namespace BenchContainerValidate {

static constexpr int REPS = 9;
static int64_t sink = 0;

template <typename F>
static void run(const char *p_name, int64_t p_iters, F &&p_fn) {
	p_fn(p_iters / 10); // Warmup.
	double times[REPS];
	for (int r = 0; r < REPS; r++) {
		const auto t0 = std::chrono::steady_clock::now();
		p_fn(p_iters);
		const auto t1 = std::chrono::steady_clock::now();
		times[r] = std::chrono::duration<double, std::nano>(t1 - t0).count() / p_iters;
	}
	std::sort(times, times + REPS);
	printf("BENCH\t%s\t%.3f\t%.3f\t%.3f\n", p_name, times[REPS / 2], times[0], times[REPS - 1]);
	fflush(stdout);
}

static void bench() {
	const int64_t N = 2'000'000;

	Vector<Variant> string_keys;
	Vector<Variant> stringname_keys;
	Vector<Variant> int_keys;
	for (int i = 0; i < 64; i++) {
		string_keys.push_back(vformat("key_%d", i));
		stringname_keys.push_back(StringName(vformat("key_%d", i)));
		int_keys.push_back(i);
	}
	const Variant *sk = string_keys.ptr();
	const Variant *ik = int_keys.ptr();

	// Dictionary lookups.
	{
		Dictionary d;
		for (int i = 0; i < 64; i++) {
			d[string_keys[i]] = i;
		}
		run("dict_untyped_has_String", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += d.has(sk[i & 63]);
			}
		});
		run("dict_untyped_getptr_String", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += d.getptr(sk[i & 63]) != nullptr;
			}
		});
		const Dictionary &cd = d;
		run("dict_untyped_const_index_String", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += cd[sk[i & 63]].get_type();
			}
		});
		run("dict_untyped_set_String", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += d.set(sk[i & 63], ik[i & 63]);
			}
		});
	}
	{
		Dictionary d;
		for (int i = 0; i < 64; i++) {
			d[int_keys[i]] = i;
		}
		run("dict_untyped_has_int", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += d.has(ik[i & 63]);
			}
		});
	}
	{
		Dictionary d;
		d.set_typed(Variant::STRING, StringName(), Variant(), Variant::INT, StringName(), Variant());
		for (int i = 0; i < 64; i++) {
			d[string_keys[i]] = i;
		}
		run("dict_typed_String_has_String", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += d.has(sk[i & 63]);
			}
		});
	}
	{
		Dictionary d;
		d.set_typed(Variant::STRING_NAME, StringName(), Variant(), Variant::INT, StringName(), Variant());
		for (int i = 0; i < 64; i++) {
			d[stringname_keys[i]] = i;
		}
		run("dict_typed_StringName_has_String (convert)", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += d.has(sk[i & 63]);
			}
		});
	}

	// Array lookups.
	{
		Array a;
		for (int i = 0; i < 8; i++) {
			a.push_back(string_keys[i]);
		}
		run("array_untyped_has_String (8 elems)", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += a.has(sk[i & 7]);
			}
		});
	}
	{
		Array a;
		a.set_typed(Variant::INT, StringName(), Variant());
		for (int i = 0; i < 8; i++) {
			a.push_back(i);
		}
		run("array_typed_int_find_int (8 elems)", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += a.find(ik[i & 7]);
			}
		});
	}
	{
		Array a;
		a.set_typed(Variant::FLOAT, StringName(), Variant());
		for (int i = 0; i < 8; i++) {
			a.push_back(double(i));
		}
		run("array_typed_float_find_int (8 elems, convert)", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				sink += a.find(ik[i & 7]);
			}
		});
	}

	// Array storing.
	{
		Array a;
		for (int i = 0; i < 16; i++) {
			a.push_back(string_keys[i]);
		}
		run("array_untyped_set_String", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				a.set(i & 15, sk[i & 63]);
			}
		});
		run("array_untyped_push_back_String (+pop_back)", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				a.push_back(sk[i & 63]);
				sink += a.pop_back().get_type();
			}
		});
	}
	{
		Array a;
		a.set_typed(Variant::FLOAT, StringName(), Variant());
		for (int i = 0; i < 16; i++) {
			a.push_back(double(i));
		}
		run("array_typed_float_push_back_int (+pop_back, convert)", N, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				a.push_back(ik[i & 63]);
				sink += a.pop_back().get_type();
			}
		});
	}
	{
		Array src;
		for (int i = 0; i < 64; i++) {
			src.push_back(i);
		}
		run("array_typed_float_append_array_int (64 elems, convert)", N / 20, [&](int64_t n) {
			for (int64_t i = 0; i < n; i++) {
				Array dst;
				dst.set_typed(Variant::FLOAT, StringName(), Variant());
				dst.append_array(src);
				sink += dst.size();
			}
		});
	}

	printf("SINK\t%lld\n", (long long)sink);
	fflush(stdout);
}

} // namespace BenchContainerValidate

REGISTER_TEST_COMMAND("bench-container-validate", &BenchContainerValidate::bench)
```

## GDScript benchmark (`bench_container_validate.gd`, empty `project.godot`)

```gdscript
extends SceneTree

const REPS := 9
const N := 1_000_000

var sink := 0


func run(bench_name: String, iters: int, fn: Callable) -> void:
	fn.call(iters / 10) # Warmup.
	var times: Array[float] = []
	for r in REPS:
		var t0 := Time.get_ticks_usec()
		fn.call(iters)
		var t1 := Time.get_ticks_usec()
		times.push_back((t1 - t0) * 1000.0 / iters)
	times.sort()
	print("BENCH\t%s\t%.3f\t%.3f\t%.3f" % [bench_name, times[REPS / 2], times[0], times[REPS - 1]])


func _init() -> void:
	var string_keys := []
	var stringname_keys := []
	var int_values := []
	for i in 64:
		string_keys.push_back("key_%d" % i)
		stringname_keys.push_back(StringName("key_%d" % i))
		int_values.push_back(i)

	var d := {}
	for i in 64:
		d[string_keys[i]] = i

	run("gd_dict_untyped_has_String", N, func(n: int) -> void:
		for i in n:
			if d.has(string_keys[i & 63]):
				sink += 1
	)
	run("gd_dict_untyped_index_get_String", N, func(n: int) -> void:
		for i in n:
			sink += d[string_keys[i & 63]]
	)
	run("gd_dict_untyped_index_set_String", N, func(n: int) -> void:
		for i in n:
			d[string_keys[i & 63]] = int_values[i & 63]
	)

	var td: Dictionary[StringName, int] = {}
	for i in 64:
		td[stringname_keys[i]] = i

	run("gd_dict_typed_StringName_has_String (convert)", N, func(n: int) -> void:
		for i in n:
			if td.has(string_keys[i & 63]):
				sink += 1
	)

	var a := []
	for i in 8:
		a.push_back(string_keys[i])

	run("gd_array_untyped_has_String (8 elems)", N, func(n: int) -> void:
		for i in n:
			if a.has(string_keys[i & 7]):
				sink += 1
	)

	var a16 := []
	for i in 16:
		a16.push_back(string_keys[i])

	run("gd_array_untyped_index_set_String", N, func(n: int) -> void:
		for i in n:
			a16[i & 15] = string_keys[i & 63]
	)

	var src := []
	for i in 64:
		src.push_back(i)

	run("gd_array_typed_float_append_array_int (64 elems, convert)", N / 20, func(n: int) -> void:
		for i in n:
			var dst: Array[float] = []
			dst.append_array(src)
			sink += dst.size()
	)

	print("SINK\t%d" % sink)
	quit()
```

