```python
#!/usr/bin/env python3
# Alternates master/branch binaries, collects per-process medians, prints a markdown table.
import statistics
import subprocess
import sys
from collections import defaultdict

S = "/private/tmp/claude-501/-Users-lukas-dev-godot-godot/d9da480a-c40d-4ea1-8544-5b6b37f01453/scratchpad"
BINS = {"master": f"{S}/godot.master", "branch": f"{S}/godot.branch"}
ROUNDS = int(sys.argv[1]) if len(sys.argv) > 1 else 5
MODE = sys.argv[2] if len(sys.argv) > 2 else "cpp"
ARGS = {
    "cpp": ["--headless", "--test", "bench-container-validate"],
    "gd": ["--headless", "--path", f"{S}/gdproj", "--script", "res://bench_container_validate.gd"],
}[MODE]

results = {k: defaultdict(list) for k in BINS}
order = []
sinks = defaultdict(set)

for r in range(ROUNDS):
    for name in (["master", "branch"] if r % 2 == 0 else ["branch", "master"]):
        out = subprocess.run([BINS[name], *ARGS],
                             capture_output=True, text=True).stdout
        for line in out.splitlines():
            parts = line.split("\t")
            if parts[0] == "BENCH":
                bench = parts[1]
                if bench not in order:
                    order.append(bench)
                results[name][bench].append(float(parts[2]))
            elif parts[0] == "SINK":
                sinks[name].add(parts[1])
        print(f"round {r + 1} {name} done", file=sys.stderr)

print(f"sinks: {dict(sinks)}", file=sys.stderr)
print("| Benchmark | master (ns/op) | branch (ns/op) | Δ | master range | branch range |")
print("|---|--:|--:|--:|--:|--:|")
for b in order:
    m = results["master"][b]
    p = results["branch"][b]
    mm, pm = statistics.median(m), statistics.median(p)
    print(f"| `{b}` | {mm:.2f} | {pm:.2f} | {(pm - mm) / mm * 100:+.1f}% | {min(m):.2f}–{max(m):.2f} | {min(p):.2f}–{max(p):.2f} |")
